def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    seqs=[]
    top=[v for v in g[0] if v]
    if top: seqs.append(top)
    run=[]
    for v in g[-1]:
        if v: run.append(v)
        elif run:
            seqs.append(run); run=[]
    if run: seqs.append(run)
    for r in range(1,h-1):
        for c in range(w):
            color=g[r][c]
            if not color: continue
            matches=[s for s in seqs if color in s]
            if len(matches)>1:
                # resolve shared colors to the bottom motif
                seq=matches[-1]
            elif matches: seq=matches[0]
            else: continue
            start=c-seq.index(color)
            for i,v in enumerate(seq):
                x=start+i
                if 0<=x<w: g[r][x]=v
    return g
